arguments.command:
python3 -c "
import re
with open('/app/dataset/genealogy_trees.txt', encoding='utf-8') as f:
    lines = f.readlines()
pat = re.compile(r'[|│]\s*([A-ZŁŚĆŹŻÓĄĘŃ][\w]*(?: [A-ZŁŚĆŹŻÓĄĘŃ][\w]*)?)\s*[|│]')
for i, line in enumerate(lines):
    for m in pat.finditer(line):
        if 'Majtyka' in m.group(1) or 'Dawid' in m.group(1):
            print(i+1, m.start(1), m.end(1), repr(m.group(1)))
"

